/* BANK TỪ VỰNG — 200 câu + 204 thẻ flashcard (mức B2) */
const VOCAB = [
/* --- Collocations --- */
{id:"v01",set:"Collocation",q:"The university has decided to ______ strict new rules on plagiarism.",opts:["do","make","take","put"],a:1,ex:"“Make rules” (đưa ra quy định) là collocation chuẩn; “do rules” sai."},
{id:"v02",set:"Collocation",q:"Regular revision will ______ a big difference to your exam performance.",opts:["do","make","take","give"],a:1,ex:"“Make a difference” — tạo ra sự khác biệt."},
{id:"v03",set:"Collocation",q:"She had to ______ a difficult decision about her career.",opts:["do","make","take","have"],a:1,ex:"“Make a decision” — ra quyết định (nhớ: take action, nhưng make a decision)."},
{id:"v04",set:"Collocation",q:"It's rude to ______ fun of someone's accent.",opts:["make","do","take","get"],a:0,ex:"“Make fun of” — chọc cười, trêu chọc ai."},
{id:"v05",set:"Collocation",q:"The team worked overtime to ______ the deadline.",opts:["reach","arrive","meet","touch"],a:2,ex:"“Meet a deadline” — kịp hạn cuối; collocation rất hay thi."},
{id:"v06",set:"Collocation",q:"Heavy traffic ______ a serious risk of delays this morning.",opts:["puts","poses","gives","makes"],a:1,ex:"“Pose a risk/threat” — tạo ra rủi ro/mối đe doạ."},
{id:"v07",set:"Collocation",q:"Always ______ notes during the lecture, not after it.",opts:["do","make","take","write"],a:2,ex:"“Take notes” — ghi chép (anh-Anh hay “make notes” nhưng VSTEP theo anh-Mỹ: take notes)."},
{id:"v08",set:"Collocation",q:"The new bridge will ______ ease congestion in the city centre.",opts:["do","make","take","play"],a:1,ex:"“Make + chores/ease...”: “help make/ease”; ở đây “help to make” → <b>make</b> đóng vai trò “contributing to easing”."},
{id:"v09",set:"Collocation",q:"He ______ a fortune selling handmade furniture online.",opts:["did","made","took","won"],a:1,ex:"“Make a fortune” — kiếm được khối tài sản."},
{id:"v10",set:"Collocation",q:"Try to ______ eye contact with the examiner during the speaking test.",opts:["keep","make","hold","do"],a:0,ex:"“Keep eye contact” (duy trì giao tiếp bằng mắt); “make eye contact” cũng đúng khi bắt đầu — với “try to” mang nghĩa duy trì, chọn <b>keep</b>."},

/* --- Phrasal verbs --- */
{id:"v11",set:"Phrasal verb",q:"The flight was called ______ because of the storm.",opts:["off","out","up","over"],a:0,ex:"“Call off” — huỷ bỏ (sự kiện, chuyến bay)."},
{id:"v12",set:"Phrasal verb",q:"I can't put ______ with this noise any longer!",opts:["on","up","off","down"],a:1,ex:"“Put up with” — chịu đựng."},
{id:"v13",set:"Phrasal verb",q:"She decided to take ______ swimming to keep fit.",opts:["up","on","in","over"],a:0,ex:"“Take up + hobby” — bắt đầu theo đuổi một sở thích."},
{id:"v14",set:"Phrasal verb",q:"The lecture was so boring that several students dozed ______.",opts:["away","off","out","up"],a:1,ex:"“Doze off” — ngủ gật."},
{id:"v15",set:"Phrasal verb",q:"Sales figures will be handed ______ to the board next Monday.",opts:["in","over","out","up"],a:1,ex:"“Hand over (to)” — bàn giao; hand in = nộp (bài), hand out = phát."},
{id:"v16",set:"Phrasal verb",q:"We've run ______ of printer paper — could you order some more?",opts:["away","out","off","down"],a:1,ex:"“Run out of” — dùng cạn, hết."},
{id:"v17",set:"Phrasal verb",q:"Don't bring ______ that argument again — we settled it last week.",opts:["up","on","about","down"],a:0,ex:"“Bring up” — nêu lại, nhắc đến (chuyện cũ)."},
{id:"v18",set:"Phrasal verb",q:"The company is looking ______ hiring fifty extra staff.",opts:["forward to","into","after","up to"],a:1,ex:"“Look into” — điều tra, xem xét; “look forward to + V-ing” là mong chờ."},
{id:"v19",set:"Phrasal verb",q:"Their marriage broke ______ after only two years.",opts:["out","down","off","in"],a:1,ex:"“Break down” (quan hệ, đàm phán) — đổ vỡ, sụp đổ; break out = bùng phát (chiến tranh, dịch)."},
{id:"v20",set:"Phrasal verb",q:"The teacher told us to get ______ with the writing task straight away.",opts:["on","over","through","across"],a:0,ex:"“Get on with something” — bắt tay làm việc gì; tiếp tục."},

/* --- Word choice (gần nghĩa) --- */
{id:"v21",set:"Chọn từ",q:"The hotel received ______ complaints about the noise from the construction site.",opts:["numerous"," numeral","plenty","many of"],a:0,ex:"“Numerous complaints” — rất nhiều lời phàn nàn (trang trọng, trước danh từ số nhiều)."},
{id:"v22",set:"Chọn từ",q:"Volunteers distributed food and blankets to ______ families.",opts:["needy","needed","needing","need"],a:0,ex:"“The needy / needy families” — những người nghèo khổ; needed = được cần."},
{id:"v23",set:"Chọn từ",q:"The documentary offers a ______ insight into rural schooling.",opts:["fascinating","fascinated","fascinate","fascination"],a:0,ex:"Tính từ chỉ tính chất gây hứng thú bổ nghĩa cho “insight” → <b>fascinating</b> (fascinated = cảm thấy hứng thú)."},
{id:"v24",set:"Chọn từ",q:"Please ______ your seatbelt before the plane takes off.",opts:["fasten","tighten","attach","connect"],a:0,ex:"“Fasten your seatbelt” — thắt dây an toàn: collocation cố định trong hàng không."},
{id:"v25",set:"Chọn từ",q:"The minister ______ the rumours of resignation as “pure speculation”.",opts:["dismissed","avoided","prevented","refused"],a:0,ex:"“Dismiss something as...” — gạt bỏ, bác bỏ (tin đồn) là..."},
{id:"v26",set:"Chọn từ",q:"There is growing ______ about the impact of AI on entry-level jobs.",opts:["concern","concerning","concerned","concerns'"],a:0,ex:"“Growing concern” (danh từ không đếm được) — mối lo ngại ngày càng lớn."},
{id:"v27",set:"Chọn từ",q:"The museum is ______ visited by over a million people a year.",opts:["currently","actually","recently","lately"],a:0,ex:"“Currently” — hiện nay (trạng từ chỉ thời gian hiện tại); actually = thật ra."},
{id:"v28",set:"Chọn từ",q:"Applicants must demonstrate a high level of ______ in English.",opts:["proficiency","efficiency","sufficiency","deficiency"],a:0,ex:"“Language proficiency” — năng lực ngôn ngữ; efficiency = hiệu suất."},
{id:"v29",set:"Chọn từ",q:"The council invested heavily in ______ transport to cut traffic emissions.",opts:["public","people","folk","mass of"],a:0,ex:"“Public transport” — giao thông công cộng."},
{id:"v30",set:"Chọn từ",q:"Rain is ______ for tomorrow's opening ceremony, so bring an umbrella.",opts:["forecast","foresee","forthcoming","forewarned"],a:0,ex:"“Rain is forecast” — mưa được dự báo (quá khứ phân từ của forecast)."},

/* --- Chủ đề: môi trường --- */
{id:"v31",set:"Môi trường",q:"Cutting down rainforests leads to the loss of ______ species.",opts:["endangered","dangerous","risky","hazardous"],a:0,ex:"“Endangered species” — các loài bị đe doạ tuyệt chủng; dangerous = nguy hiểm (gây hại)."},
{id:"v32",set:"Môi trường",q:"The factory was fined for dumping untreated ______ into the river.",opts:["sewage","litter","fumes","wasting"],a:0,ex:"“Sewage” — nước thải; fumes = khói khí thải; litter = rác rưởi vứt bừa."},
{id:"v33",set:"Môi trường",q:"Switching to renewable energy will reduce our carbon ______.",opts:["footprint","trace","print","step"],a:0,ex:"“Carbon footprint” — dấu chân các bon: collocation môi trường kinh điển."},
{id:"v34",set:"Môi trường",q:"Single-use plastics should be ______ out completely by 2030.",opts:["phased","removed","passed","erased"],a:0,ex:"“Phase out” — loại bỏ dần từng giai đoạn."},
{id:"v35",set:"Môi trường",q:"Climate change is ______ by the burning of fossil fuels.",opts:["accelerated","hurried","rushed","pressed"],a:0,ex:"“Be accelerated” — bị đẩy nhanh (tiến trình); các từ còn lại không collocate với tiến trình khí hậu."},

/* --- Chủ đề: giáo dục & công việc --- */
{id:"v36",set:"Giáo dục/Công việc",q:"Graduates with good soft skills stand a better chance of ______ employment.",opts:["securing","holding","grasping","seizing"],a:0,ex:"“Secure a job/employment” — đảm bảo có được việc làm: collocation công việc."},
{id:"v37",set:"Giáo dục/Công việc",q:"The scholarship covers tuition fees but not living ______.",opts:["costs","expenses'","charges","prices"],a:0,ex:"“Living costs/expenses” — chi phí sinh hoạt; ở đây cần danh từ số nhiều làm tân ngữ: living <b>costs</b>."},
{id:"v38",set:"Giáo dục/Công việc",q:"She was ______ from assistant to team leader within a year.",opts:["promoted","elevated","upgraded","advanced"],a:0,ex:"“Be promoted (from ... to ...)” — được thăng chức."},
{id:"v39",set:"Giáo dục/Công việc",q:"A well-written CV can make a strong first ______ on recruiters.",opts:["impression","impact","image","opinion"],a:0,ex:"“Make an impression on somebody” — tạo ấn tượng với ai."},
{id:"v40",set:"Giáo dục/Công việc",q:"The course combines ______ learning with real workplace placements.",opts:["theoretical","theoretic","theory","theoretically"],a:0,ex:"Cần tính từ bổ nghĩa cho “learning”: <b>theoretical</b> learning — học lý thuyết."},

/* --- Chủ đề: công nghệ --- */
{id:"v41",set:"Công nghệ",q:"The app was ______ from the store after privacy complaints.",opts:["withdrawn","retired","extracted","subtracted"],a:0,ex:"“Withdraw a product” — rút sản phẩm khỏi thị trường."},
{id:"v42",set:"Công nghệ",q:"Hackers gained ______ to the database through a weak password.",opts:["access","entrance","entry","admission"],a:0,ex:"“Gain/have access to” — có quyền truy cập: collocation công nghệ cố định."},
{id:"v43",set:"Công nghệ",q:"The new processor is significantly faster and more energy-______.",opts:["efficient","effective","efficacious","economical"],a:0,ex:"“Energy-efficient” — tiết kiệm năng lượng (thiết bị)."},
{id:"v44",set:"Công nghệ",q:"Video calls help ______ the gap between remote team members.",opts:["bridge","close","fill","link"],a:0,ex:"“Bridge the gap” — thu hẹp khoảng cách: idiom rất B2."},
{id:"v45",set:"Công nghệ",q:"Users are advised to back ______ their data regularly.",opts:["up","on","in","over"],a:0,ex:"“Back up data” — sao lưu dữ liệu."},

/* --- Chủ đề: sức khoẻ --- */
{id:"v46",set:"Sức khoẻ",q:"Doctors recommend a balanced diet and regular exercise to ______ good health.",opts:["maintain","persist","continue","endure"],a:0,ex:"“Maintain good health” — duy trì sức khoẻ tốt."},
{id:"v47",set:"Sức khoẻ",q:"Lack of sleep can ______ your concentration and memory.",opts:["impair","harmful","damage to","injure"],a:0,ex:"“Impair” (động từ) — làm suy giảm (chức năng); harmful là tính từ."},
{id:"v48",set:"Sức khoẻ",q:"The health campaign encourages people to ______ up smoking.",opts:["give","quit","leave","stop from"],a:0,ex:"“Give up smoking” — bỏ thuốc; quit smoking cũng đúng nhưng sau “up” chỉ give phù hợp."},
{id:"v49",set:"Sức khoẻ",q:"Regular check-ups help ______ diseases early.",opts:["detect","discover","find out","explore"],a:0,ex:"“Detect a disease early” — phát hiện bệnh sớm (y tế dùng detect)."},
{id:"v50",set:"Sức khoẻ",q:"Too much screen time before bed can ______ with your sleep.",opts:["interfere","interrupt","disturb","invade"],a:0,ex:"“Interfere with” — can thiệp/cản trở (giấc ngủ); interrupt = cắt ngang."},

/* --- Chủ đề: xã hội & du lịch --- */
{id:"v51",set:"Xã hội/Du lịch",q:"The old town attracts thousands of tourists ______ its preserved architecture.",opts:["thanks to","due of","because","owing of"],a:0,ex:"“Thanks to + danh từ” — nhờ có; because phải đi với mệnh đề."},
{id:"v52",set:"Xã hội/Du lịch",q:"Mass tourism can put enormous ______ on local infrastructure.",opts:["strain","stress","tension","pressure'"],a:0,ex:"“Put a strain on” — gây áp lực lớn lên (hạ tầng)."},
{id:"v53",set:"Xã hội/Du lịch",q:"We booked a ______ hotel close to the conference venue.",opts:["convenient","comfortable","convenience","comfort"],a:0,ex:"Cần tính từ bổ nghĩa cho “hotel”; cả convenient/comfortable đều hợp ngữ pháp nhưng vị trí + gần hội trường → <b>convenient</b> (tiện vị trí)."},
{id:"v54",set:"Xã hội/Du lịch",q:"The festival is held to ______ the town's founding anniversary.",opts:["commemorate","memorise","remember to","recollect"],a:0,ex:"“Commemorate an anniversary” — kỷ niệm (sự kiện) một cách trang trọng."},
{id:"v55",set:"Xã hội/Du lịch",q:"Local residents were ______ about the plans for a new airport.",opts:["consulted","asked for","questioned for","demanded"],a:0,ex:"“Consult somebody about something” — lấy ý kiến ai về việc gì."},
{id:"v56",set:"Xã hội/Du lịch",q:"The number of backpackers has risen ______ in the past decade.",opts:["sharply","sharply'","strong","heavy"],a:0,ex:"Cần trạng từ bổ nghĩa cho “risen”: risen <b>sharply</b> — tăng vọt."},
{id:"v57",set:"Xã hội/Du lịch",q:"Homestays offer visitors an authentic ______ of daily family life.",opts:["glimpse","glance","sight","view"],a:0,ex:"“A glimpse of” — cái nhìn thoáng qua; get a glimpse of daily life = được nhìn/trải nghiệm thoáng qua đời sống thường ngày."},
{id:"v58",set:"Xã hội/Du lịch",q:"Cities should ______ more cycle lanes to encourage green commuting.",opts:["allocate","deliver","assign","allot to"],a:0,ex:"“Allocate resources/lanes (for a purpose)” — phân bổ nguồn lực."},
{id:"v59",set:"Xã hội/Du lịch",q:"The volunteer scheme has had a positive ______ on the whole neighbourhood.",opts:["impact","affect","effect to","influence to"],a:0,ex:"“Have an impact on” — có tác động đến."},
{id:"v60",set:"Xã hội/Du lịch",q:"Street food vendors are an inseparable part of the city's cultural ______.",opts:["identity","identification","identical","identities'"],a:0,ex:"“Cultural identity” — bản sắc văn hoá."},

/* --- Thành ngữ (Idioms) --- */
{id:"v61",set:"Thành ngữ",q:"Learning a second language is hard, but don't give up — practice makes ______.",opts:["perfect","better","progress","master"],a:0,ex:"Thành ngữ “practice makes <b>perfect</b>” — có công mài sắt có ngày nên kim."},
{id:"v62",set:"Thành ngữ",q:"The negotiations were tough, but finally both sides saw eye to ______ and signed the deal.",opts:["eye","hand","mind","face"],a:0,ex:"“See eye to eye” — nhất trí, đồng quan điểm với nhau."},
{id:"v63",set:"Thành ngữ",q:"I wanted to tell her the truth, but at the last minute I got cold ______.",opts:["feet","hands","sweat","blood"],a:0,ex:"“Get cold feet” — mất hết can đảm, chùn bước vào phút chót."},
{id:"v64",set:"Thành ngữ",q:"The manager rejected our plan, so we had to go back to the drawing ______ and rethink the budget.",opts:["board","table","paper","room"],a:0,ex:"“(Go) back to the drawing board” — quay lại làm từ đầu sau thất bại."},
{id:"v65",set:"Thành ngữ",q:"Don't mention his failed business — it's still a sore ______ for him.",opts:["point","mark","scar","bruise"],a:0,ex:"“A sore point” — vấn đề nhạy cảm, nỗi đau không muốn nhắc đến."},
{id:"v66",set:"Thành ngữ",q:"Working double shifts for months really ______ its toll on her health.",opts:["takes","makes","gives","puts"],a:0,ex:"“Take its toll on” — gây tổn hại dần dần (sức khoẻ, tinh thần)."},
{id:"v67",set:"Thành ngữ",q:"The two brothers are like chalk and ______ — completely different personalities.",opts:["cheese","milk","butter","bread"],a:0,ex:"Thành ngữ Anh-Anh “like chalk and cheese” — khác nhau một trời một vực."},
{id:"v68",set:"Thành ngữ",q:"She's been burning the ______ at both ends, studying for finals while working full-time.",opts:["candle","lamp","midnight","lights"],a:0,ex:"“Burn the candle at both ends” — làm việc/học tập đến kiệt sức từ hai phía."},
{id:"v69",set:"Thành ngữ",q:"The new evidence put the investigation in a completely different ______.",opts:["light","lamp","shade","angle"],a:0,ex:"“Put/cast something in a different light” — khiến sự việc được nhìn nhận theo cách khác."},
{id:"v70",set:"Thành ngữ",q:"After ten failed auditions she was ready to throw in the ______ and give up acting.",opts:["towel","sponge","hat","ring"],a:0,ex:"“Throw in the towel” — bỏ cuộc (xuất phát từ quyền anh)."},

/* --- Cặp từ dễ nhầm (Confusing pairs) --- */
{id:"v71",set:"Từ dễ nhầm",q:"The heavy rain didn't ______ our plans — we moved the picnic indoors.",opts:["effect","affect","infect","defect"],a:1,ex:"“Affect” là động từ (ảnh hưởng); “effect” là danh từ (hiệu ứng)."},
{id:"v72",set:"Từ dễ nhầm",q:"Interest rates are expected to ______ steadily over the next year.",opts:["raise","rise","arise","arouse"],a:1,ex:"“Rise” là nội động từ (tự tăng); “raise” là ngoại động từ, cần tân ngữ (raise prices)."},
{id:"v73",set:"Từ dễ nhầm",q:"The museum displays many ______ documents from the Nguyen dynasty.",opts:["historic","historical","history","historian"],a:1,ex:"“Historical” = thuộc về lịch sử (tài liệu, sự kiện); “historic” = có ý nghĩa lịch sử trọng đại."},
{id:"v74",set:"Từ dễ nhầm",q:"The new engine is far more ______ on fuel than the old model.",opts:["economic","economical","economy","economics"],a:1,ex:"“Economical” = tiết kiệm; “economic” = thuộc kinh tế (economic growth)."},
{id:"v75",set:"Từ dễ nhầm",q:"It would be ______ to book tickets early, as prices rise closer to Tet.",opts:["sensitive","sensible","sensual","senseless"],a:1,ex:"“Sensible” = khôn ngoan, hợp lý; “sensitive” = nhạy cảm."},
{id:"v76",set:"Từ dễ nhầm",q:"The lecturer spoke so quietly that his voice was barely ______.",opts:["audible","visible","edible","legible"],a:0,ex:"“Audible” = nghe được; “legible” = đọc được (chữ viết); visible = nhìn thấy."},
{id:"v77",set:"Từ dễ nhầm",q:"Students should be ______ to their teachers and classmates.",opts:["respectful","respectable","respective","respected"],a:0,ex:"“Respectful” = biết kính trọng (chủ động tôn trọng); “respectable” = đáng kính; “respective” = tương ứng."},
{id:"v78",set:"Từ dễ nhầm",q:"Guests ______ the chef on the excellent five-course meal.",opts:["complemented","complimented","completed","complied"],a:1,ex:"“Compliment somebody on something” = khen ai về điều gì; “complement” = bổ sung cho nhau."},
{id:"v79",set:"Từ dễ nhầm",q:"The two reports give ______ accounts of the incident — one must be wrong.",opts:["alternate","alternative","alternating","alternated"],a:1,ex:"“Alternative” = khác, thay thế (hai bản khác nhau); “alternate” = xen kẽ, luân phiên."},
{id:"v80",set:"Từ dễ nhầm",q:"The ______ reason for her resignation was the long daily commute.",opts:["principal","principle","principally","principles"],a:0,ex:"“Principal” (tính từ) = chính, chủ yếu; “principle” (danh từ) = nguyên tắc."},

/* --- Chủ đề: Kinh tế & Tiền bạc --- */
{id:"v81",set:"Kinh tế",q:"The startup managed to ______ enough funding to launch its first product.",opts:["raise","rise","lift","grow"],a:0,ex:"“Raise funding/capital” — huy động vốn: collocation kinh doanh chuẩn."},
{id:"v82",set:"Kinh tế",q:"Inflation has sharply increased the cost of ______ in major cities.",opts:["alive","life","living","live"],a:2,ex:"“Cost of living” — chi phí sinh hoạt, giá sinh hoạt."},
{id:"v83",set:"Kinh tế",q:"Many small shops went out of ______ during the prolonged lockdown.",opts:["order","business","work","shop"],a:1,ex:"“Go out of business” — phá sản, đóng cửa kinh doanh."},
{id:"v84",set:"Kinh tế",q:"The company reported record ______ for the third quarter, up 18% on last year.",opts:["profits","prophets","benefits","gains"],a:0,ex:"“Report profits” — công bố lợi nhuận; đừng nhầm với “prophets” (nhà tiên tri)."},
{id:"v85",set:"Kinh tế",q:"Students should learn to manage their ______ early to avoid debt.",opts:["finances","finance's","financially","financier"],a:0,ex:"“Finances” (số nhiều) = tình hình tài chính cá nhân; financier = nhà tài trợ."},

/* --- Chủ đề: Khoa học & Nghiên cứu --- */
{id:"v86",set:"Khoa học",q:"The researchers carried ______ a series of experiments on sleep patterns.",opts:["out","on","off","through"],a:0,ex:"“Carry out an experiment/research” — tiến hành thí nghiệm/nghiên cứu."},
{id:"v87",set:"Khoa học",q:"The study provides strong ______ that regular exercise improves memory.",opts:["proof","evidence","witness","clue"],a:1,ex:"“Evidence” (không đếm được) = bằng chứng khoa học; “proof” mang tính chứng minh dứt khoát, hiếm dùng trong khoa học."},
{id:"v88",set:"Khoa học",q:"Their findings were published in a leading scientific ______.",opts:["magazine","journal","diary","novel"],a:1,ex:"“Scientific journal” — tạp chí khoa học chuyên ngành."},
{id:"v89",set:"Khoa học",q:"The data was ______ over a period of ten years from hospitals nationwide.",opts:["gathered","guessed","grown","guided"],a:0,ex:"“Gather/collect data” — thu thập dữ liệu."},
{id:"v90",set:"Khoa học",q:"Before publication, the paper had to be checked by other experts in the field — a process called peer ______.",opts:["check","control","review","audit"],a:2,ex:"“Peer review” — phản biện đồng nghiệp: quy trình chuẩn của xuất bản học thuật."},

/* --- Chủ đề: Truyền thông & Báo chí --- */
{id:"v91",set:"Truyền thông",q:"The story made ______ news across all the major networks.",opts:["headline","heading","head","first"],a:0,ex:"“Make headline news” — trở thành tin lớn trang nhất."},
{id:"v92",set:"Truyền thông",q:"The article cited an anonymous ______ close to the investigation.",opts:["sauce","source","resource","inform"],a:1,ex:"“A source” — nguồn tin; “anonymous source” = nguồn tin ẩn danh."},
{id:"v93",set:"Truyền thông",q:"Within hours, the clip had gone ______ on social media.",opts:["viral","virus","virtual","violent"],a:0,ex:"“Go viral” — lan truyền chóng mặt trên mạng."},
{id:"v94",set:"Truyền thông",q:"The reporter was praised for her ______ coverage of the conflict.",opts:["bias","biased","unbiased","biasing"],a:2,ex:"“Unbiased coverage” — đưa tin khách quan, không thiên vị (bias = thiên kiến)."},
{id:"v95",set:"Truyền thông",q:"The channel broadcasts a daily news ______ at 7 p.m.",opts:["bulletin","bullet","ballot","ballet"],a:0,ex:"“News bulletin” — bản tin; đừng nhầm với ballot (phiếu bầu) hay ballet (múa)."},

/* --- Chủ đề: Pháp luật & Trật tự --- */
{id:"v96",set:"Pháp luật",q:"The suspect was released because there wasn't enough ______ to charge him.",opts:["evidence","proof of","witnesses'","jury"],a:0,ex:"“Enough evidence to charge somebody” — đủ chứng cứ để truy tố."},
{id:"v97",set:"Pháp luật",q:"Shoplifting is a minor ______ but it can still lead to a criminal record.",opts:["sin","crime","offence","fault"],a:2,ex:"“Offence” = hành vi vi phạm pháp luật; “crime” thường nghiêm trọng hơn. Minor offence — lỗi nhẹ."},
{id:"v98",set:"Pháp luật",q:"The judge ______ him to two years' probation for the fraud.",opts:["punished","sentenced","ordered","judged"],a:1,ex:"“Sentence somebody to…” — tuyên án (bản án cụ thể); punish = phạt nói chung."},
{id:"v99",set:"Pháp luật",q:"Witnesses are legally ______ to tell the truth in court.",opts:["obliged","forced","made","caused"],a:0,ex:"“Be (legally) obliged to do” — bị ràng buộc bởi pháp luật, có nghĩa vụ."},
{id:"v100",set:"Pháp luật",q:"Cybercrime is on the ______ as more services move online.",opts:["rise","raise","increase","growth"],a:0,ex:"Cụm cố định “be on the rise” — đang gia tăng; “on the increase” cũng đúng nhưng không đi với the."},

/* --- Collocation (tiếp) --- */
{id:"v101",set:"Collocation",q:"The new traffic rules will come into ______ next month.",opts:["effect","affect","force of","power"],a:0,ex:"“Come into effect” — có hiệu lực, bắt đầu được áp dụng."},
{id:"v102",set:"Collocation",q:"We need to ______ into account the cultural differences between the two markets.",opts:["do","make","take","put"],a:2,ex:"“Take something into account” — tính đến, xem xét đến."},
{id:"v103",set:"Collocation",q:"She ______ great pleasure in mentoring younger colleagues.",opts:["makes","takes","does","gets"],a:1,ex:"“Take pleasure in doing something” — thích thú, lấy làm vui khi làm gì."},
{id:"v104",set:"Collocation",q:"The scandal ______ serious damage to the minister's reputation.",opts:["did","made","gave","put"],a:0,ex:"“Do damage to” — gây tổn hại cho (danh tiếng, uy tín)."},
{id:"v105",set:"Collocation",q:"Could you ______ me a favour and check this letter before I send it?",opts:["do","make","give","take"],a:0,ex:"“Do somebody a favour” — giúp ai một việc."},
{id:"v106",set:"Collocation",q:"The new medicine had no ______ on his condition at all.",opts:["affect","effect","impression","influencing"],a:1,ex:"“Have an effect on” — có tác động lên; đừng nhầm với affect (động từ)."},
{id:"v107",set:"Collocation",q:"Students must ______ close attention during the lab demonstration.",opts:["pay","make","give","take"],a:0,ex:"“Pay attention to” — chú ý đến."},
{id:"v108",set:"Collocation",q:"The government should ______ higher priority to public education.",opts:["give","make","do","put"],a:0,ex:"“Give priority to” — ưu tiên cho."},
{id:"v109",set:"Collocation",q:"Her farewell speech ______ a deep impression on everyone in the room.",opts:["did","made","took","gave"],a:1,ex:"“Make an impression on somebody” — tạo ấn tượng sâu sắc với ai."},
{id:"v110",set:"Collocation",q:"Please ______ sure all the windows are locked before you leave.",opts:["do","get","make","take"],a:2,ex:"“Make sure” — đảm bảo, kiểm tra cho chắc."},

/* --- Phrasal verbs (tiếp) --- */
{id:"v111",set:"Phrasal verb",q:"The quarterly meeting has been put ______ until next Friday.",opts:["off","out","away","back"],a:0,ex:"“Put off” — hoãn lại, dời lịch."},
{id:"v112",set:"Phrasal verb",q:"I came ______ an old class photo while cleaning the attic.",opts:["across","into","up","over"],a:0,ex:"“Come across” — tình cờ tìm thấy, bắt gặp."},
{id:"v113",set:"Phrasal verb",q:"The company is trying to cut ______ on staff training costs.",opts:["down","off","out","back"],a:0,ex:"“Cut down on” — cắt giảm (chi phí, lượng tiêu thụ)."},
{id:"v114",set:"Phrasal verb",q:"Could you fill ______ this application form, please?",opts:["in","on","for","with"],a:0,ex:"“Fill in/out a form” — điền vào mẫu đơn."},
{id:"v115",set:"Phrasal verb",q:"She really takes ______ her mother — they are both so patient.",opts:["after","from","up","on"],a:0,ex:"“Take after somebody” — giống (bố mẹ, người thân) về tính cách/ngoại hình."},
{id:"v116",set:"Phrasal verb",q:"He turned ______ the job offer because the salary was too low.",opts:["down","off","away","out"],a:0,ex:"“Turn down” — từ chối (lời đề nghị, lời mời)."},
{id:"v117",set:"Phrasal verb",q:"The fire alarm went ______ in the middle of the lecture.",opts:["off","out","on","over"],a:0,ex:"“Go off” — reo vang (chuông, báo động); cũng là “nổ” (bom)."},
{id:"v118",set:"Phrasal verb",q:"We'll have to figure ______ a cheaper way to get to the test centre.",opts:["out","off","through","over"],a:0,ex:"“Figure out” — tìm ra, hiểu ra cách làm."},
{id:"v119",set:"Phrasal verb",q:"My car broke ______ on the way to the exam, so I nearly missed it.",opts:["down","off","out","up"],a:0,ex:"“Break down” — hỏng, chết máy (xe cộ, thiết bị)."},
{id:"v120",set:"Phrasal verb",q:"The research team carried ______ the experiment despite limited funding.",opts:["out","on","off","forward"],a:0,ex:"“Carry out” — tiến hành, thực hiện (thí nghiệm, nghiên cứu, kế hoạch)."},

/* --- Thành ngữ (tiếp) --- */
{id:"v121",set:"Thành ngữ",q:"I passed the driving test by the skin of my ______ — one more error and I'd have failed.",opts:["teeth","hands","lips","nails"],a:0,ex:"“By the skin of one's teeth” — suýt soát, sát sao mới qua được."},
{id:"v122",set:"Thành ngữ",q:"Stop beating around the ______ and tell me what actually happened.",opts:["bush","tree","field","topic"],a:0,ex:"“Beat around the bush” — nói vòng vo tam quốc, không vào vấn đề chính."},
{id:"v123",set:"Thành ngữ",q:"The new manager hit the ______ running and reorganised the whole team in a month.",opts:["ground","floor","road","track"],a:0,ex:"“Hit the ground running” — bắt tay vào việc ngay lập tức, đầy hiệu quả."},
{id:"v124",set:"Thành ngữ",q:"After the twelve-hour flight, I slept like a ______.",opts:["log","stone","baby of","pillow"],a:0,ex:"“Sleep like a log” — ngủ say như chết."},
{id:"v125",set:"Thành ngữ",q:"Trying to convince him to change his mind now is like flogging a dead ______.",opts:["horse","dog","cow","donkey"],a:0,ex:"“Flog a dead horse” — phí công làm việc đã vô vọng."},
{id:"v126",set:"Thành ngữ",q:"Don't put all your eggs in one ______ — apply to several universities.",opts:["basket","box","bag","pot"],a:0,ex:"“Put all your eggs in one basket” — dồn hết trứng vào một giỏ: liều hết vào một phương án."},
{id:"v127",set:"Thành ngữ",q:"The interviewer had a gut ______ that the candidate was exaggerating his experience.",opts:["feeling","idea","mind","sense of"],a:0,ex:"“Gut feeling” — linh cảm, trực giác mách bảo."},
{id:"v128",set:"Thành ngữ",q:"Losing that stressful job turned out to be a blessing in ______.",opts:["disguise","hiding","cover","secret"],a:0,ex:"“A blessing in disguise” — trong cái rủi có cái may."},
{id:"v129",set:"Thành ngữ",q:"The new tax instructions are as clear as ______ — nobody understands them.",opts:["mud","crystal","water","glass"],a:0,ex:"“As clear as mud” — (mỉa mai) rối rắm khó hiểu, chẳng rõ ràng gì."},
{id:"v130",set:"Thành ngữ",q:"We've been studying since dawn — let's call it a ______.",opts:["day","night","week","time"],a:0,ex:"“Call it a day” — kết thúc buổi làm việc/học, nghỉ tay."},

/* --- Từ dễ nhầm (tiếp) --- */
{id:"v131",set:"Từ dễ nhầm",q:"The ______ rate in the region has fallen below five percent.",opts:["unemployment","employed","employment","employer"],a:0,ex:"“Unemployment rate” — tỷ lệ thất nghiệp (danh từ + rate)."},
{id:"v132",set:"Từ dễ nhầm",q:"We spent the whole afternoon ______ through the botanical garden.",opts:["wandering","wondering","wondered","wandering'"],a:0,ex:"“Wander” = đi dạo, lang thang; “wonder” = thắc mắc, tự hỏi."},
{id:"v133",set:"Từ dễ nhầm",q:"The election results were quite ______ — nobody expected such a low turnout.",opts:["surprising","surprised","surprise","surprisingly"],a:0,ex:"Cần tính từ chỉ tính chất gây ngạc nhiên của sự việc → <b>surprising</b>; surprised = bản thân cảm thấy ngạc nhiên."},
{id:"v134",set:"Từ dễ nhầm",q:"Please accept my ______ apologies for the scheduling error.",opts:["sincere","sincerely","honest of","real of"],a:0,ex:"“Sincere apologies” (tính từ + danh từ); sincerely là trạng từ: “I sincerely apologise”."},
{id:"v135",set:"Từ dễ nhầm",q:"The quiet fishing village has hardly changed ______ the war ended.",opts:["since","for","during","ago"],a:0,ex:"“Since + mốc/mệnh đề quá khứ” dùng với thì hiện tại hoàn thành; for + khoảng thời gian."},
{id:"v136",set:"Từ dễ nhầm",q:"The documentary is well ______ watching if you are interested in space travel.",opts:["worth","worthy","deserving","valuable"],a:0,ex:"“Be worth + V-ing” — đáng để làm gì; worthy dùng “worthy of + danh từ/V-ing”."},
{id:"v137",set:"Từ dễ nhầm",q:"I can't ______ to buy a new laptop this year — the repair bill took all my savings.",opts:["afford","afford to","allow","permit"],a:0,ex:"“Can't afford to do something” — không đủ tiền/khả năng để làm gì."},
{id:"v138",set:"Từ dễ nhầm",q:"Students are expected to ______ their assignments before Friday.",opts:["hand in","hand over","hand out","hand up"],a:0,ex:"“Hand in” = nộp (bài); hand over = bàn giao; hand out = phát."},
{id:"v139",set:"Từ dễ nhầm",q:"The two neighbours signed a ______ agreement to end the trade dispute.",opts:["bilateral","bilingual","double of","two-side"],a:0,ex:"“Bilateral” = song phương (hai bên); “bilingual” = song ngữ."},
{id:"v140",set:"Từ dễ nhầm",q:"She has an amazingly ______ memory — she remembers everyone's name after one meeting.",opts:["retentive","attentive","sensitive","reactive"],a:0,ex:"“A retentive memory” — trí nhớ bền, nhớ dai; attentive = chăm chú."},

/* --- Chủ đề: Giới từ (mới) --- */
{id:"v141",set:"Giới từ",q:"The success of the whole project depends ______ effective teamwork.",opts:["on","in","at","of"],a:0,ex:"“Depend on” — phụ thuộc vào: cặp động từ + giới từ kinh điển hay thi."},
{id:"v142",set:"Giới từ",q:"She apologised ______ being late for the job interview.",opts:["for","about","at","to"],a:0,ex:"“Apologise for (doing) something” — xin lỗi về việc gì."},
{id:"v143",set:"Giới từ",q:"Young people today are deeply interested ______ environmental issues.",opts:["in","on","about","at"],a:0,ex:"“Be interested in” — quan tâm đến."},
{id:"v144",set:"Giới từ",q:"The supervisor insisted ______ checking everyone's report personally.",opts:["on","at","in","for"],a:0,ex:"“Insist on (doing) something” — khăng khăng đòi làm gì."},
{id:"v145",set:"Giới từ",q:"He was accused ______ cheating in the entrance exam.",opts:["of","for","with","about"],a:0,ex:"“Accuse somebody of (doing) something” — buộc tội ai làm gì."},
{id:"v146",set:"Giới từ",q:"The new visa regulation applies ______ all international students.",opts:["to","for","with","on"],a:0,ex:"“Apply to somebody/something” — áp dụng cho; apply for = nộp đơn xin."},
{id:"v147",set:"Giới từ",q:"Everyone congratulated her ______ winning the national scholarship.",opts:["on","about","for","with"],a:0,ex:"“Congratulate somebody on something” — chúc mừng ai về việc gì."},
{id:"v148",set:"Giới từ",q:"Local residents are increasingly worried ______ the rising crime rate.",opts:["about","for","of","on"],a:0,ex:"“Be worried about” — lo lắng về."},
{id:"v149",set:"Giới từ",q:"The firm invested heavily ______ renewable energy technology.",opts:["in","on","at","for"],a:0,ex:"“Invest in” — đầu tư vào."},
{id:"v150",set:"Giới từ",q:"Her parents strongly disapprove ______ her plan to drop out of university.",opts:["of","on","for","about"],a:0,ex:"“Disapprove of” — không tán thành, phản đối việc gì."},

/* --- Chủ đề: Liên từ & kết nối (mới) --- */
{id:"v151",set:"Liên từ",q:"______ the heavy rain, the outdoor graduation ceremony continued as planned.",opts:["Despite","Although","Because","Because of it"],a:0,ex:"“Despite/In spite of + danh từ” — mặc dù; although phải đi với mệnh đề có chủ-vị."},
{id:"v152",set:"Liên từ",q:"The course was extremely demanding. ______, most students passed with distinction.",opts:["Nevertheless","Therefore","Moreover","Otherwise"],a:0,ex:"“Nevertheless” — tuy vậy (đối lập); therefore = do đó (kết quả)."},
{id:"v153",set:"Liên từ",q:"Revise your vocabulary notes regularly; ______, you will forget most of them within weeks.",opts:["otherwise","therefore","moreover","whereas"],a:0,ex:"“Otherwise” — nếu không thì (cảnh báo hậu quả)."},
{id:"v154",set:"Liên từ",q:"______ studying for eight hours straight, she still felt unprepared for the test.",opts:["Despite","In spite","Although","Even"],a:0,ex:"“Despite + V-ing” — mặc dù đã làm gì; “in spite” thiếu of; although cần mệnh đề."},
{id:"v155",set:"Liên từ",q:"The internship is unpaid; ______, it offers invaluable industry contacts.",opts:["in return","therefore","likewise","instead of"],a:0,ex:"“In return” — bù lại (điểm lợi đối lập điểm hại)."},
{id:"v156",set:"Liên từ",q:"Both parents work twelve-hour shifts. ______, the children spend most evenings alone.",opts:["Consequently","Nonetheless","Otherwise","Meanwhile"],a:0,ex:"“Consequently” — hệ quả là, do đó (quan hệ nhân-quả)."},
{id:"v157",set:"Liên từ",q:"______ is she an outstanding student, but she is also a gifted violinist.",opts:["Not only","Hardly","Scarcely","Rarely of"],a:0,ex:"“Not only + đảo ngữ … but also” — không những… mà còn; cấu trúc đảo ngữ điểm cao."},
{id:"v158",set:"Liên từ",q:"The essay was poorly structured ______ the student had plenty of time to prepare.",opts:["even though","despite","because of","in spite of"],a:0,ex:"“Even though + mệnh đề” — mặc dù rằng; despite/in spite of chỉ đi với danh từ/cụm danh từ."},
{id:"v159",set:"Liên từ",q:"You'd better choose the evening course, ______ you won't be able to attend classes.",opts:["otherwise","unless","therefore","besides"],a:0,ex:"“Otherwise” — nếu không thì; unless = trừ khi (mang nghĩa khác)."},
{id:"v160",set:"Liên từ",q:"______ being visibly exhausted, the guest speaker answered questions for another hour.",opts:["Despite","Although","However","Because"],a:0,ex:"“Despite + danh từ/V-ing” — mặc dù; although/however không đứng trước cụm V-ing."},

/* --- Chủ đề: Dạng từ (mới) --- */
{id:"v161",set:"Dạng từ",q:"The ______ of the new suspension bridge will take at least two years.",opts:["construction","constructive","constructing","constructor"],a:0,ex:"Cần danh từ sau mạo từ The: “construction” — sự thi công/xây dựng."},
{id:"v162",set:"Dạng từ",q:"She gave a highly ______ performance in the final interview round.",opts:["convincing","convinced","convince","convincingly"],a:0,ex:"Tính từ bổ nghĩa cho “performance”: <b>convincing</b> (thuyết phục); convinced = cảm thấy tin chắc."},
{id:"v163",set:"Dạng từ",q:"There has been a noticeable ______ in air quality since the ban on old motorbikes.",opts:["improvement","improving","improved","improvable"],a:0,ex:"Cần danh từ: “improvement” — sự cải thiện."},
{id:"v164",set:"Dạng từ",q:"The ______ of online learning has transformed university education.",opts:["advent","arrival of","entrance","invention to"],a:0,ex:"“The advent of something” — sự ra đời/xuất hiện của: cụm cố định văn học thuật."},
{id:"v165",set:"Dạng từ",q:"The assembly instructions were so ______ that hardly anyone could follow them.",opts:["complicated","complicating","complicate","complexity"],a:0,ex:"Cần tính từ sau “so … that”: <b>complicated</b> — phức tạp, rắc rối."},
{id:"v166",set:"Dạng từ",q:"Tourism makes a significant ______ to the local economy.",opts:["contribution","contributing","contributed","contributor"],a:0,ex:"“Make a contribution to” — đóng góp vào (danh từ)."},
{id:"v167",set:"Dạng từ",q:"Her close ______ to detail makes her an excellent copy editor.",opts:["attention","attentive","attending","attentively"],a:0,ex:"“Attention to detail” — sự chú ý đến chi tiết: cụm cố định."},
{id:"v168",set:"Dạng từ",q:"The city centre has become increasingly ______ during the tourist season.",opts:["crowded","crowding","crowd","crowdedness"],a:0,ex:"Cần tính từ sau become: <b>crowded</b> — đông đúc."},
{id:"v169",set:"Dạng từ",q:"We need a more ______ approach to urban waste management.",opts:["sustainable","sustained","sustaining","sustainability"],a:0,ex:"Tính từ bổ nghĩa “approach”: <b>sustainable</b> — bền vững; sustainability là danh từ."},
{id:"v170",set:"Dạng từ",q:"The lecture was both informative and highly ______.",opts:["entertaining","entertained","entertainment","entertain"],a:0,ex:"Tính từ song song với “informative”: <b>entertaining</b> — thú vị, lôi cuốn."},

/* --- Bổ sung các chủ đề --- */
{id:"v171",set:"Môi trường",q:"The river was severely ______ by chemical waste from the textile factory.",opts:["polluted","pollution","polluting","pollutant"],a:0,ex:"Câu bị động: “was polluted by” — bị ô nhiễm bởi."},
{id:"v172",set:"Môi trường",q:"We should ______ more on renewable sources such as solar and wind power.",opts:["rely","count to","depend of","focus in"],a:0,ex:"“Rely on” — dựa vào, phụ thuộc vào (nguồn năng lượng)."},
{id:"v173",set:"Môi trường",q:"Melting sea ice threatens the ______ of polar bears in the Arctic.",opts:["survival","surviving","survive","survivors"],a:0,ex:"Cần danh từ: “survival” — sự tồn tại, sống còn."},
{id:"v174",set:"Môi trường",q:"Factories must treat waste water before releasing it into the ______.",opts:["environment","environmental","environmentally","environments'"],a:0,ex:"Cần danh từ: “the environment” — môi trường (tự nhiên)."},
{id:"v175",set:"Môi trường",q:"______ farming practices help protect the soil for future generations.",opts:["Sustainable","Sustained","Sustaining","Sustainably"],a:0,ex:"“Sustainable farming” — nông nghiệp bền vững: cụm rất hay gặp trong đề."},
{id:"v176",set:"Sức khoẻ",q:"The vaccine provides long-term ______ against the virus.",opts:["immunity","immune","immunising","immunisation'"],a:0,ex:"“Provide immunity against” — tạo miễn dịch với (danh từ)."},
{id:"v177",set:"Sức khoẻ",q:"She was ______ to hospital with severe chest pains last night.",opts:["admitted","admitting","entered","accepted for"],a:0,ex:"“Be admitted to hospital” — được nhập viện."},
{id:"v178",set:"Sức khoẻ",q:"A high-sugar diet significantly increases the ______ of developing diabetes.",opts:["risk","danger to","threat of","hazard"],a:0,ex:"“The risk of doing something” — nguy cơ mắc phải."},
{id:"v179",set:"Sức khoẻ",q:"The new cancer drug is still ______ clinical trials.",opts:["undergoing","under","within","passing for"],a:0,ex:"“Undergo trials” — đang trong quá trình thử nghiệm lâm sàng."},
{id:"v180",set:"Sức khoẻ",q:"Mental wellbeing is just as important as ______ health.",opts:["physical","physic","physique","bodily of"],a:0,ex:"“Physical health” — sức khoẻ thể chất, đối lập mental health."},
{id:"v181",set:"Giáo dục/Công việc",q:"She graduated from university with first-class ______ in English literature.",opts:["honours","honorary","honoured","honestly"],a:0,ex:"“Graduate with honours” — tốt nghiệp loại giỏi/xuất sắc."},
{id:"v182",set:"Giáo dục/Công việc",q:"The university now offers flexible ______ learning for working adults.",opts:["distance","distant","distanced","faraway"],a:0,ex:"“Distance learning” — học từ xa/đào tạo trực tuyến."},
{id:"v183",set:"Giáo dục/Công việc",q:"Employers value candidates who can stay calm under ______.",opts:["pressure","press","stress of","pressing"],a:0,ex:"“Under pressure” — chịu áp lực: collocation công sở."},
{id:"v184",set:"Giáo dục/Công việc",q:"New employees are on a three-month ______ before getting a permanent contract.",opts:["probation","probationary of","trial to","test"],a:0,ex:"“On probation” — trong thời gian thử việc."},
{id:"v185",set:"Giáo dục/Công việc",q:"The internship gave her valuable hands-on ______ in digital marketing.",opts:["experience","experienced","experiencing","expertise of"],a:0,ex:"“Hands-on experience” — kinh nghiệm thực tế (experience không đếm được ở đây)."},
{id:"v186",set:"Công nghệ",q:"The company stores all customer data on a secure ______.",opts:["server","service","serve","servant"],a:0,ex:"“Server” — máy chủ lưu trữ dữ liệu."},
{id:"v187",set:"Công nghệ",q:"You need to ______ the app before you can use it on your phone.",opts:["install","instant","instalment","instil"],a:0,ex:"“Install an app” — cài đặt ứng dụng."},
{id:"v188",set:"Công nghệ",q:"Social media feeds are designed to be highly ______, keeping users scrolling for hours.",opts:["addictive","addicted","addicting","addiction"],a:0,ex:"“Addictive” (tính từ) — gây nghiện; addicted = bị nghiện (người)."},
{id:"v189",set:"Công nghệ",q:"The rapid ______ of artificial intelligence raises many ethical questions.",opts:["rise","raise","arising of","risen"],a:0,ex:"“The rise of something” — sự trỗi dậy của (danh từ); raise là ngoại động từ."},
{id:"v190",set:"Công nghệ",q:"The website crashed because of a sudden ______ in traffic after the announcement.",opts:["surge","flood to","rise of","jump for"],a:0,ex:"“A surge in” — sự tăng đột ngột (lưu lượng, nhu cầu)."},
{id:"v191",set:"Kinh tế",q:"The government introduced tax ______ to encourage small businesses to hire more staff.",opts:["breaks","interrupts","pauses of","stops"],a:0,ex:"“Tax breaks” — ưu đãi/giảm thuế: collocation kinh tế."},
{id:"v192",set:"Kinh tế",q:"Unemployment benefit supports people who are temporarily out of ______.",opts:["work","job","employment of","jobs"],a:0,ex:"“Out of work” — thất nghiệp: cụm cố định không mạo từ."},
{id:"v193",set:"Kinh tế",q:"The stock market is highly ______ right now — share prices change every hour.",opts:["volatile","volatility","variable of","flexible to"],a:0,ex:"“Volatile” (tính từ) — biến động mạnh, bất ổn (thị trường)."},
{id:"v194",set:"Kinh tế",q:"She invested her savings by buying ______ in a renewable energy company.",opts:["shares","sharing","shared","shareholders"],a:0,ex:"“Buy shares in a company” — mua cổ phần của công ty."},
{id:"v195",set:"Kinh tế",q:"The central bank raised interest ______ again to keep inflation under control.",opts:["rates","ratios","scales","ranks"],a:0,ex:"“Interest rates” — lãi suất: collocation tài chính chuẩn."},
{id:"v196",set:"Truyền thông",q:"The newspaper was criticised for its ______ coverage of the election campaign.",opts:["biased","bias","biasing","unbiasedly"],a:0,ex:"“Biased coverage” — đưa tin thiên lệch; unbiased = khách quan."},
{id:"v197",set:"Truyền thông",q:"Citizen journalism lets ordinary people ______ news events as they happen.",opts:["cover","hide","mask","conceal"],a:0,ex:"“Cover a story/event” — đưa tin, tác nghiệp về sự kiện."},
{id:"v198",set:"Truyền thông",q:"The presidential debate was broadcast ______ on national television.",opts:["live","alive","lively","living"],a:0,ex:"“Broadcast live” — phát sóng trực tiếp; live /laɪv/ là trạng từ ở đây."},
{id:"v199",set:"Truyền thông",q:"The channel was fined for spreading ______ information about the vaccine.",opts:["misleading","mistaken","false of","faulty"],a:0,ex:"“Misleading information” — thông tin gây hiểu lầm; fake/false information cũng đúng về nghĩa nhưng câu này nhấn tính dẫn dắt sai."},
{id:"v200",set:"Truyền thông",q:"Responsible journalists always ______ their sources before publishing a story.",opts:["verify","clarify","justify","identify for"],a:0,ex:"“Verify sources/information” — kiểm chứng nguồn tin: đạo đức nghề báo."}
];

